import {
  useState,
  useRef,
  useEffect,
  useCallback,
  startTransition,
  type Dispatch,
  type SetStateAction,
} from 'react';
import { useSelector } from 'react-redux';
import type { InternalAccount } from '@metamask/keyring-internal-api';
import log from 'loglevel';
import {
  type MarkAsReadNotificationsParam,
  type INotification,
} from '@metamask/notification-services-controller/notification-services';
import {
  createOnChainTriggers,
  fetchAndUpdateMetamaskNotifications,
  markMetamaskNotificationsAsRead,
  enableMetamaskNotifications,
  disableMetamaskNotifications,
} from '../../store/actions';
import {
  setUserHasTurnedOffNotificationsOnce,
  updateNotificationSubscriptionExpiration,
} from '../../contexts/metamask-notifications/notification-storage-keys';
import { getDataCollectionForMarketing } from '../../selectors/metametrics';
import { selectIsFeatureAnnouncementsEnabled } from '../../selectors/metamask-notifications/metamask-notifications';
import { useDispatch } from '../../store/hooks';

/**
 * useState that only applies updates while mounted. Prevents
 * "state updates on unmounted components" when async work completes after unmount.
 *
 * @param initialValue - The initial value of the state.
 */
export function useSafeState<TValue>(
  initialValue: TValue,
): [TValue, Dispatch<SetStateAction<TValue>>] {
  const [state, setState] = useState<TValue>(initialValue);
  const isMountedRef = useRef(true);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const setSafeState = useCallback((value: SetStateAction<TValue>) => {
    if (isMountedRef.current) {
      setState(value);
    }
  }, []);

  return [state, setSafeState];
}

// Define KeyringType interface
type KeyringType = {
  type: string;
};

// Define AccountType interface
export type AccountType = InternalAccount & {
  balance: string;
  keyring: KeyringType;
  label: string;
};

/**
 * Custom hook to fetch and update the list of notifications.
 * Manages loading and error states internally.
 *
 * @returns An object containing the `listNotifications` function, loading state, and error state.
 */
export function useListNotifications(): {
  listNotifications: () => Promise<INotification[] | undefined>;
  notificationsData?: INotification[];
  isLoading: boolean;
  error?: unknown;
} {
  const dispatch = useDispatch();

  const [loading, setLoading] = useSafeState<boolean>(false);
  const [error, setError] = useSafeState<unknown>(null);
  const [notificationsData, setNotificationsData] = useSafeState<
    INotification[] | undefined
  >(undefined);

  const listNotifications = useCallback(async (): Promise<
    INotification[] | undefined
  > => {
    setLoading(true);
    setError(null);

    const urlParams = new URLSearchParams(window.location.search);
    const previewToken = urlParams.get('previewToken');

    try {
      const data = await dispatch(
        fetchAndUpdateMetamaskNotifications(previewToken ?? undefined),
      );
      startTransition(() => {
        setNotificationsData(data as unknown as INotification[]);
        setLoading(false);
      });
      return data as unknown as INotification[];
    } catch (e) {
      log.error(e);
      setError(e instanceof Error ? e.message : 'An unexpected error occurred');
      setLoading(false);
      throw e;
    }
  }, [dispatch, setLoading, setError, setNotificationsData]);

  return {
    listNotifications,
    notificationsData,
    isLoading: loading,
    error,
  };
}

/**
 * Custom hook to enable notifications by creating on-chain triggers.
 * It manages loading and error states internally.
 *
 * @returns An object containing the `enableNotifications` function, loading state, and error state.
 */
export function useCreateNotifications(): {
  createNotifications: () => Promise<void>;
  error: string | null;
} {
  const dispatch = useDispatch();
  const [error, setError] = useSafeState<string | null>(null);

  const createNotifications = useCallback(async () => {
    setError(null);

    try {
      await dispatch(createOnChainTriggers());
      await updateNotificationSubscriptionExpiration();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'An unexpected error occurred');
      log.error(e);
      throw e;
    }
  }, [dispatch, setError]);

  return {
    createNotifications,
    error,
  };
}

/**
 * Custom hook to enable MetaMask notifications.
 * This hook encapsulates the logic for enabling notifications, handling loading and error states.
 * It uses Redux to dispatch actions related to notifications.
 *
 * @returns An object containing:
 * - `enableNotifications`: A function that triggers the enabling of notifications.
 * - `loading`: A boolean indicating if the enabling process is ongoing.
 * - `error`: A string or null value representing any error that occurred during the process.
 */
export function useEnableNotifications(): {
  enableNotifications: () => Promise<void>;
  error: string | null;
} {
  const dispatch = useDispatch();
  const hasMarketingConsent = Boolean(
    useSelector(getDataCollectionForMarketing),
  );
  const isFeatureAnnouncementsEnabled =
    useSelector(selectIsFeatureAnnouncementsEnabled) ?? true;

  const [error, setError] = useSafeState<string | null>(null);

  const enableNotifications = useCallback(async () => {
    setError(null);

    try {
      await dispatch(
        enableMetamaskNotifications({
          hasMarketingConsent,
          productAnnouncementEnabled: isFeatureAnnouncementsEnabled,
        }),
      );
      await updateNotificationSubscriptionExpiration();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'An unexpected error occurred');
      log.error(e);
      throw e;
    }
  }, [dispatch, hasMarketingConsent, isFeatureAnnouncementsEnabled, setError]);

  return {
    enableNotifications,
    error,
  };
}

/**
 * Custom hook to disable notifications by deleting on-chain triggers associated with accounts.
 * It also disables snap and feature announcements. Manages loading and error states internally.
 *
 * @returns An object containing the `disableNotifications` function, loading state, and error state.
 */
export function useDisableNotifications(): {
  disableNotifications: () => Promise<void>;
  error: string | null;
} {
  const dispatch = useDispatch();
  const [error, setError] = useSafeState<string | null>(null);

  const disableNotifications = useCallback(async () => {
    setError(null);

    try {
      await dispatch(disableMetamaskNotifications());
      await setUserHasTurnedOffNotificationsOnce();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'An unexpected error occurred');
      log.error(e);
      throw e;
    }
  }, [dispatch, setError]);

  return {
    disableNotifications,
    error,
  };
}

/**
 * Provides a function to mark notifications as read. This hook does not take parameters itself,
 * but returns a function that accepts the notification parameters when called.
 *
 * @returns An object containing the `markNotificationAsRead` function which takes a `notifications`
 * parameter of type `MarkAsReadNotificationsParam` and marks those notifications as read.
 */
export function useMarkNotificationAsRead(): {
  markNotificationAsRead: (
    notifications: MarkAsReadNotificationsParam,
  ) => Promise<void>;
} {
  const dispatch = useDispatch();

  const markNotificationAsRead = useCallback(
    async (notifications: MarkAsReadNotificationsParam) => {
      try {
        dispatch(markMetamaskNotificationsAsRead(notifications));
      } catch (e) {
        log.error(e);
        throw e;
      }
    },
    [dispatch],
  );

  return {
    markNotificationAsRead,
  };
}
